package com.harshith.leave.service; import com.harshith.leave.entity.*; import com.harshith.leave.exception.*; import com.harshith.leave.repository.*; import org.springframework.stereotype.Service; import java.time.temporal.ChronoUnit; import java.util.*; @Service public class LeaveService { private final LeaveRequestRepository lr; private final EmployeeRepository er; private final LeaveBalanceRepository br; public LeaveService(LeaveRequestRepository lr,EmployeeRepository er,LeaveBalanceRepository br){this.lr=lr;this.er=er;this.br=br;} public LeaveRequest apply(Long eid,LeaveRequest r){Employee e=er.findById(eid).orElseThrow(()->new ResourceNotFoundException("Employee not found: "+eid));if(r.getStartDate().isAfter(r.getEndDate()))throw new BusinessException("Start date cannot be after end date");r.setEmployee(e);r.setStatus(LeaveStatus.PENDING);return lr.save(r);} public List<LeaveRequest> all(){return lr.findAll();} public LeaveRequest get(Long id){return lr.findById(id).orElseThrow(()->new ResourceNotFoundException("Leave request not found: "+id));} public List<LeaveRequest> byEmployee(Long id){er.findById(id).orElseThrow(()->new ResourceNotFoundException("Employee not found: "+id));return lr.findByEmployeeId(id);} public LeaveRequest approve(Long id){LeaveRequest r=get(id);if(r.getStatus()!=LeaveStatus.PENDING)throw new BusinessException("Only pending requests can be approved");int days=(int)(ChronoUnit.DAYS.between(r.getStartDate(),r.getEndDate())+1);LeaveBalance b=br.findByEmployeeId(r.getEmployee().getId()).orElseThrow(()->new ResourceNotFoundException("Leave balance not found"));int a=r.getLeaveType()==LeaveType.CASUAL?b.getCasualLeave():r.getLeaveType()==LeaveType.SICK?b.getSickLeave():b.getEarnedLeave();if(days>a)throw new BusinessException("Insufficient leave balance");b.deduct(r.getLeaveType(),days);br.save(b);r.setStatus(LeaveStatus.APPROVED);return lr.save(r);} public LeaveRequest reject(Long id){return change(id,LeaveStatus.REJECTED);} public LeaveRequest cancel(Long id){return change(id,LeaveStatus.CANCELLED);} private LeaveRequest change(Long id,LeaveStatus s){LeaveRequest r=get(id);if(r.getStatus()!=LeaveStatus.PENDING)throw new BusinessException("Only pending requests can be changed");r.setStatus(s);return lr.save(r);} }